CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text UNIQUE NOT NULL, phone text NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS businesses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, slug text UNIQUE NOT NULL, type text NOT NULL CHECK (type IN ('barbershop','salon')), phone text, location text, timezone text NOT NULL DEFAULT 'Africa/Nairobi', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS business_members (business_id uuid NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'owner', PRIMARY KEY(business_id,user_id));
CREATE TABLE IF NOT EXISTS services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, name text NOT NULL, price_kes integer, duration_minutes integer, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, name text NOT NULL, phone text NOT NULL, whatsapp_phone text, preferred_service_id uuid REFERENCES services(id), preferred_staff text, frequency_days integer, last_visit_at timestamptz, source text NOT NULL DEFAULT 'MANUAL', sms_allowed boolean NOT NULL DEFAULT false, whatsapp_allowed boolean NOT NULL DEFAULT false, marketing_allowed boolean NOT NULL DEFAULT false, opted_out boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(business_id,phone));
CREATE TABLE IF NOT EXISTS appointments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, customer_id uuid NOT NULL REFERENCES customers(id), service_id uuid REFERENCES services(id), staff_name text, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'booked', created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS appointments_active_slot_idx ON appointments(business_id, staff_name, starts_at) WHERE status IN ('booked','confirmed');
CREATE TABLE IF NOT EXISTS subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid UNIQUE NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending', payment_reference text, payment_phone text, paid_at timestamptz, renews_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS customers_business_due_idx ON customers(business_id,last_visit_at,frequency_days);
